<script setup>import SafeImage from '../components/common/SafeImage.vue';defineProps({services:Array,categories:Array,activeCategory:String});defineEmits(['filter','open-service'])</script><template><main class="page"><h1>游乌东</h1><div class="filter"><button @click="$emit('filter','all')">全部</button><button v-for="c in categories" :key="c.id" @click="$emit('filter',c.id)">{{c.label}}</button></div><div class="service-grid"><article v-for="item in services" :key="item.id" class="service-card" @click="$emit('open-service',item.id)"><SafeImage :src="item.image" :alt="item.imageAlt" :label="item.title" loading="lazy"/><div><h3>{{item.title}}</h3><p>{{item.tags.join(' · ')}}</p></div></article></div></main></template>
